import{_ as o,c as n,o as r,a0 as s}from"./chunks/framework.cBVQg-HI.js";const c=JSON.parse('{"title":"什么是 Python","description":"","frontmatter":{},"headers":[],"relativePath":"python_course/index.md","filePath":"python_course/index.md"}'),e={name:"python_course/index.md"};function a(i,t,l,g,p,_){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="什么是-python" tabindex="-1">什么是 Python <a class="header-anchor" href="#什么是-python" aria-label="Permalink to &quot;什么是 Python&quot;">​</a></h1><p>Python 是一种<strong>高级编程语言</strong>，结合了解释性、编译性、互动性和面向对象的特性。它以<strong>简洁易读</strong>的语法设计而闻名，非常适合初学者和专业开发者。</p><p>Python 的主要特点包括：</p><ul><li><strong>解释型语言</strong>：无需编译，代码可以直接运行，类似于 PHP 和 Perl。</li><li><strong>交互式</strong>：支持在终端输入代码并立即执行，方便测试和调试。&gt; - <strong>面向对象</strong>：支持面向对象编程，允许代码封装在对象中。</li><li><strong>易学易用</strong>：语法简单，关键字少，代码结构清晰。</li><li><strong>跨平台</strong>：支持在 UNIX、Windows 和 Mac 等多个平台运行。</li><li><strong>丰富的标准库</strong>：内置大量模块，支持文件操作、网络编程、数据库访问等功能。&gt; - <strong>可扩展性</strong>：可以通过 C 或 C++ 编写高性能模块，并在 Python 中调用。</li><li><strong>支持 GUI</strong>：可以开发图形用户界面应用程序。</li><li><strong>嵌入性</strong>：可以嵌入到其他语言（如 C/C++）的程序中，提供脚本化能力。</li></ul><p>Python 由 Guido van Rossum 于 20 世纪 80 年代末设计，受多种语言（如 ABC、C、SmallTalk 等）启发。它的开源特性和强大的社区支持使其成为<strong>全球最流行的编程语言之一</strong>，广泛应用于数据科学、人工智能、Web 开发、自动化等领域。</p><hr><p><strong>👋 第一次使用 CodeNova？</strong> 查看 <a href="/course/c20260816214006b677/guide/">使用指南 →</a></p>',7)])])}const h=o(e,[["render",a]]);export{c as __pageData,h as default};
